import { convertToModelMessages, streamText, type UIMessage } from "ai";
import { clientIp, checkInput, checkRate } from "@/lib/guard";
import { MODEL_ID, qwen } from "@/lib/model";
import { PROMPTS, isToyKey } from "@/lib/prompts";

// Hobby 档 300s 封顶，这也是最大值
export const maxDuration = 300;
export const runtime = "nodejs";

function textOf(message: UIMessage | undefined): string {
  if (!message) return "";
  return (message.parts ?? [])
    .filter((p): p is { type: "text"; text: string } => p.type === "text")
    .map((p) => p.text)
    .join("");
}

export async function POST(req: Request) {
  let body: { toy?: unknown; messages?: UIMessage[] };
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "你这话，本号没听清。" }, { status: 400 });
  }

  const { toy, messages } = body;

  if (!isToyKey(toy)) {
    return Response.json({ error: "没这个窗口。" }, { status: 400 });
  }

  const guard = checkInput(textOf(messages?.[messages.length - 1]));
  if (!guard.ok) return Response.json({ error: guard.reason }, { status: 400 });

  const rate = checkRate(clientIp(req));
  if (!rate.ok) return Response.json({ error: rate.reason }, { status: 429 });

  try {
    const result = streamText({
      model: qwen(MODEL_ID),
      system: PROMPTS[toy],
      messages: await convertToModelMessages(messages ?? []),
      temperature: 0.9,
      // 给上游单独设 deadline，别让挂死的调用拖满 300s
      abortSignal: AbortSignal.timeout(120_000),
    });

    return result.toUIMessageStreamResponse({
      onError: () => "歇工了",
    });
  } catch {
    return Response.json({ error: "歇工了" }, { status: 503 });
  }
}
